17	package org.springframework.samples.petclinic.util;
18	
19	import java.time.LocalDate;
20	
21	/**
22	 * Helpers for the membership points and numeric level a pet owner is assigned. Points are derived
23	 * from the owner's own fields together with their tenure (elapsed fiscal years since registration),
24	 * and the level is a banding of those points.
25	 */
26	public final class Memberships {
27	
28	    /**
29	     * The lowest membership level every owner starts from.
30	     */
31	    public static final int BASE_LEVEL = 1;
32	
33	    /**
34	     * The highest membership level reachable. Level 4 is only reached with 6 or more points, and the
35	     * only route to 6 points is qualifying tenure (see {@link #TENURE_LEVEL_FISCAL_YEARS}) on top of
36	     * the other factors.
37	     */
38	    public static final int MAX_LEVEL = 4;
39	
40	    /**
41	     * The points added when an email is present.
42	     */
43	    public static final int EMAIL_POINTS = 2;
44	
45	    /**
46	     * The points added when {@code namesakeCount} is 0.
47	     */
48	    public static final int UNIQUE_NAME_POINTS = 1;
49	
50	    /**
51	     * The points added for a household of {@link #HOUSEHOLD_POINTS_THRESHOLD} or more.
52	     */
53	    public static final int HOUSEHOLD_POINTS = 2;
54	
55	    /**
56	     * The household size at or above which {@link #HOUSEHOLD_POINTS} are added.
57	     */
58	    public static final int HOUSEHOLD_POINTS_THRESHOLD = 3;
59	
60	    /**
61	     * The points added for tenure over {@link #TENURE_LEVEL_FISCAL_YEARS} elapsed fiscal years.
62	     */
63	    public static final int TENURE_POINTS = 3;
64	
65	    /**
66	     * The tenure, in elapsed fiscal years (see
67	     * {@link org.springframework.samples.petclinic.util.FiscalYears#elapsedFiscalYears}), that must
68	     * be strictly exceeded to earn the tenure points. At or below it the tenure points are not
69	     * granted.
70	     */
71	    public static final int TENURE_LEVEL_FISCAL_YEARS = 1;
72	
73	    private Memberships() {
74	    }
75	
76	    /**
77	     * Computes an owner's membership points. Starts at 0; adds {@link #EMAIL_POINTS} when an email is
78	     * present; adds {@link #UNIQUE_NAME_POINTS} when {@code namesakeCount} is 0; adds
79	     * {@link #HOUSEHOLD_POINTS} for a household of {@link #HOUSEHOLD_POINTS_THRESHOLD} or more; adds
80	     * {@link #TENURE_POINTS} when the owner's tenure is more than {@link #TENURE_LEVEL_FISCAL_YEARS}
81	     * elapsed fiscal years.
82	     *
83	     * @param email            the owner's email, or {@code null} when absent
84	     * @param namesakeCount    the owner's namesake count, or {@code null} when unknown
85	     * @param householdSize    the owner's household size, or {@code null} when unknown
86	     * @param registrationDate the owner's registration date, or {@code null} when unknown; tenure is
87	     *                         measured from this date to today
88	     * @return the membership points, 0 or more
89	     */
90	    public static int membershipPoints(String email, Integer namesakeCount, Integer householdSize,
91	            LocalDate registrationDate) {
92	        int points = 0;
93	        if (email != null) {
94	            points += EMAIL_POINTS;
95	        }
96	        if (namesakeCount != null && namesakeCount == 0) {
97	            points += UNIQUE_NAME_POINTS;
98	        }
99	        if (householdSize != null && householdSize >= HOUSEHOLD_POINTS_THRESHOLD) {
100	            points += HOUSEHOLD_POINTS;
101	        }
102	        if (hasQualifyingTenure(registrationDate)) {
103	            points += TENURE_POINTS;
104	        }
105	        return points;
106	    }
107	
108	    /**
109	     * Maps membership points to a numeric membership level: 1 (0-1 points), 2 (2-3), 3 (4-5),
110	     * 4 (6 or more).
111	     *
112	     * @param points the owner's membership points (see {@link #membershipPoints})
113	     * @return the membership level, from {@value #BASE_LEVEL} to {@value #MAX_LEVEL}
114	     */
115	    public static int membershipLevel(int points) {
116	        if (points >= 6) {
117	            return 4;
118	        }
119	        if (points >= 4) {
120	            return 3;
121	        }
122	        if (points >= 2) {
123	            return 2;
124	        }
125	        return BASE_LEVEL;
126	    }
127	
128	    /**
129	     * Computes an owner's numeric membership level from their fields, by mapping
130	     * {@link #membershipPoints} through {@link #membershipLevel(int)}.
131	     *
132	     * @param email            the owner's email, or {@code null} when absent
133	     * @param namesakeCount    the owner's namesake count, or {@code null} when unknown
134	     * @param householdSize    the owner's household size, or {@code null} when unknown
135	     * @param registrationDate the owner's registration date, or {@code null} when unknown; tenure is
136	     *                         measured from this date to today
137	     * @return the membership level, from {@value #BASE_LEVEL} to {@value #MAX_LEVEL}
138	     */
139	    public static int membershipLevel(String email, Integer namesakeCount, Integer householdSize,
140	            LocalDate registrationDate) {
141	        return membershipLevel(membershipPoints(email, namesakeCount, householdSize, registrationDate));
142	    }
143	
144	    /**
145	     * Whether the given registration date represents tenure of more than
146	     * {@link #TENURE_LEVEL_FISCAL_YEARS} elapsed fiscal years as of today. A {@code null} (or future)
147	     * registration date never qualifies.
148	     *
149	     * @param registrationDate the owner's registration date, or {@code null} when unknown
150	     * @return {@code true} when tenure strictly exceeds {@link #TENURE_LEVEL_FISCAL_YEARS} elapsed
151	     *         fiscal years
152	     */
153	    public static boolean hasQualifyingTenure(LocalDate registrationDate) {
154	        if (registrationDate == null) {
155	            return false;
156	        }
157	        return FiscalYears.elapsedFiscalYears(registrationDate, LocalDate.now()) > TENURE_LEVEL_FISCAL_YEARS;
158	    }
159	}
