753	    @Override
754	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
755	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
756	        if (currentOwner == null) {
757	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
758	        }
759	        currentOwner.setAddress(ownerFieldsDto.getAddress());
760	        currentOwner.setCity(ownerFieldsDto.getCity());
761	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
762	        currentOwner.setLastName(ownerFieldsDto.getLastName());
763	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
764	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
765	        this.clinicService.saveOwner(currentOwner);
766	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
767	    }
768	
769	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
770	    @Transactional
771	    @Override
772	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
773	        Owner owner = this.clinicService.findOwnerById(ownerId);
774	        if (owner == null) {
775	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
776	        }
777	        this.clinicService.deleteOwner(owner);
778	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
779	    }
780	
781	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
782	    @Override
783	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
784	        Owner owner = this.clinicService.findOwnerById(ownerId);
785	        if (owner == null) {
786	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
787	        }
788	        HttpHeaders headers = new HttpHeaders();
789	        Pet pet = petMapper.toPet(petFieldsDto);
790	        owner.setId(ownerId);
791	        pet.setOwner(owner);
792	        pet.getType().setName(null);
793	        this.clinicService.savePet(pet);
794	        PetDto petDto = petMapper.toPetDto(pet);
795	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
796	            .buildAndExpand(pet.getId()).toUri());
797	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
798	    }
799	
800	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
801	    @Override
802	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
803	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
804	        if (currentOwner != null) {
805	            Pet currentPet = this.clinicService.findPetById(petId);
806	            if (currentPet != null) {
807	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
808	                currentPet.setName(petFieldsDto.getName());
809	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
810	                this.clinicService.savePet(currentPet);
811	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
812	            }
813	        }
814	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
815	    }
816	
817	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
818	    @Override
819	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
820	        HttpHeaders headers = new HttpHeaders();
821	        Visit visit = visitMapper.toVisit(visitFieldsDto);
822	        Pet pet = new Pet();
823	        pet.setId(petId);
824	        visit.setPet(pet);
825	        this.clinicService.saveVisit(visit);
826	        VisitDto visitDto = visitMapper.toVisitDto(visit);
827	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
828	            .buildAndExpand(visit.getId()).toUri());
829	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
830	    }
831	
832	
833	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
834	    @Override
835	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
836	        Owner owner = this.clinicService.findOwnerById(ownerId);
837	        if (owner != null) {
838	            Pet pet = owner.getPet(petId);
839	            if (pet != null) {
